() => {
  const files = listFiles();
  const relevantFiles = files.filter(file => 
    file.includes("memory") || 
    file.includes("validation") || 
    file.includes("consolidation") ||
    file.includes("deterministic") ||
    file.includes("citation") ||
    file.includes("function")
  );
  return relevantFiles;
}

() => {
  const allFiles = listFiles();
  const relevantFiles = allFiles.filter(file => 
    file.includes("memory") || 
    file.includes("validation") || 
    file.includes("consolidation") || 
    file.includes("deterministic") || 
    file.includes("citation") || 
    file.includes("function") ||
    file.includes("primitive") ||
    file.includes("procedure")
  );
  return relevantFiles;
}

() => {
  const allFiles = listFiles();
  return allFiles.filter(file => 
    !file.startsWith(".") && 
    !file.startsWith("dist/") && 
    !file.includes(".map") && 
    !file.includes(".LICENSE") && 
    (file.endsWith(".ts") || file.endsWith(".js") || file.endsWith(".md"))
  );
}

() => {
  const allFiles = listFiles();
  return allFiles.filter(file => 
    file.endsWith(".ts") || file.endsWith(".js") || file.endsWith(".md")
  ).filter(file => !file.startsWith("dist/"));
}

() => {
  const allFiles = listFiles();
  return allFiles.filter(file => 
    (file.endsWith(".ts") || file.endsWith(".js")) && 
    !file.startsWith("dist/") && 
    !file.startsWith(".")
  );
}

() => {
  const allFiles = listFiles();
  const tsJsFiles = allFiles.filter(file => 
    (file.endsWith(".ts") || file.endsWith(".js")) && 
    !file.startsWith("dist/")
  );
  return tsJsFiles;
}

() => {
  const allFiles = listFiles();
  return allFiles.filter(file => 
    file.includes("src") || 
    file.includes("lib") || 
    file.includes("test") || 
    file.includes("spec")
  ).filter(file => !file.startsWith("dist/"));
}

() => {
  const allFiles = listFiles();
  return allFiles.filter(file => 
    file.includes("src/") || 
    file.includes("lib/") || 
    file.includes("tests/") || 
    file.includes("spec/")
  );
}
